  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap" rel="stylesheet">
  <style>
    :root{--pine-950:#061a15;--pine-900:#09251d;--pine-850:#0d3027;--pine-800:#123b30;--pine-700:#1b5242;--acid:#dffc62;--ember:#f27b4a;--cream:#fffdf6;--oat:#f0ecdf;--moss:#b7c9a3;--ink:#16231e;--line:rgba(9,37,29,.12);--shadow:0 28px 80px -48px rgba(6,26,21,.62);--card-shadow:0 20px 54px -38px rgba(6,26,21,.48)}
    *{box-sizing:border-box}html{background:var(--oat);scroll-behavior:smooth}body{margin:0;overflow-x:hidden;background:var(--oat);color:var(--ink);font-family:"DM Sans",sans-serif;text-rendering:optimizeLegibility}button,input,select{font:inherit}button,a{touch-action:manipulation}a{color:inherit;text-decoration:none}img{display:block;max-width:100%}[hidden]{display:none!important}::selection{background:var(--acid);color:var(--pine-950)}
    .shell{width:min(1460px,calc(100% - 32px));margin-inline:auto}.grain{position:relative}.grain:after{content:"";position:absolute;inset:0;pointer-events:none;z-index:2;opacity:.07;mix-blend-mode:soft-light;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='.56'/%3E%3C/svg%3E")}.topo{background-image:radial-gradient(circle at 14% 16%,rgba(223,252,98,.14),transparent 20%),radial-gradient(circle at 88% 20%,rgba(242,123,74,.13),transparent 16%),url("data:image/svg+xml,%3Csvg width='760' height='760' viewBox='0 0 760 760' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' stroke='%23fff' stroke-opacity='.06' stroke-width='1.05'%3E%3Cpath d='M74 206c43-106 166-167 278-119 89 39 107 147 52 218-51 66-143 59-194 124-58 73-49 188-142 228-91 38-186-37-164-132 20-89 111-106 122-190 8-57-5-88 48-129Z'/%3E%3Cpath d='M112 231c34-81 128-126 214-90 69 29 82 113 41 167-39 50-110 45-150 95-44 55-38 144-109 174-70 29-143-29-126-102 15-68 85-81 94-146 6-43-4-67 36-98Z'/%3E%3Cpath d='M493 410c57-79 161-89 227-18 60 64 24 169-55 198-71 26-142-17-201 28-52 40-62 123-129 129-74 6-126-73-84-135 38-56 112-39 155-92 35-43 39-79 87-110Z'/%3E%3C/g%3E%3C/svg%3E");background-size:auto,auto,760px 760px}
    .site-header{position:sticky;top:0;z-index:50;padding:12px 0;background:linear-gradient(180deg,rgba(240,236,223,.95),rgba(240,236,223,.77),transparent)}.nav{display:flex;align-items:center;gap:16px;padding:10px 12px 10px 16px;border:1px solid rgba(255,255,255,.12);border-radius:22px;background:rgba(6,26,21,.87);box-shadow:0 24px 70px -46px rgba(0,0,0,.9);backdrop-filter:blur(22px) saturate(130%);color:#fff}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:42px;height:42px;flex:0 0 auto;border:1px solid rgba(223,252,98,.42);border-radius:15px;background:rgba(223,252,98,.08);color:var(--acid)}.brand-copy{min-width:0;line-height:1}.brand-copy strong{display:block;font-family:"Fraunces",serif;font-size:18px;font-weight:600;letter-spacing:-.02em}.brand-copy span{display:block;margin-top:5px;color:rgba(255,255,255,.5);font-size:10px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;white-space:nowrap}.main-nav{display:flex;align-items:center;gap:6px;margin-left:auto}.main-nav a{padding:10px 12px;border-radius:12px;color:rgba(255,255,255,.68);font-size:13px;font-weight:600;transition:.2s ease}.main-nav a:hover{background:rgba(255,255,255,.07);color:#fff}.nav-actions{display:flex;align-items:center;gap:8px}.ticket-cta{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:0 16px;border-radius:13px;background:var(--acid);color:var(--pine-950);font-size:13px;font-weight:800;white-space:nowrap}.menu-btn{display:none;place-items:center;width:40px;height:40px;border:0;border-radius:13px;background:rgba(255,255,255,.07);color:#fff;cursor:pointer}
    .layout{display:grid;grid-template-columns:250px minmax(0,1fr);gap:24px;padding:18px 0 84px}.sidebar{position:sticky;top:92px;align-self:start;padding:18px;border:1px solid var(--line);border-radius:26px;background:rgba(255,253,246,.78);box-shadow:var(--card-shadow);backdrop-filter:blur(18px)}.profile-mini{display:flex;align-items:center;gap:12px;padding:8px 8px 20px;border-bottom:1px solid var(--line)}.avatar{display:grid;place-items:center;width:50px;height:50px;border-radius:18px;background:var(--pine-900);color:var(--acid);font-family:"Fraunces",serif;font-size:18px;font-weight:700}.profile-mini strong{display:block;font-size:14px}.profile-mini span span{display:block;margin-top:4px;color:rgba(22,35,30,.54);font-size:11px}.side-nav{display:grid;gap:6px;padding:16px 0}.side-nav a{display:flex;align-items:center;gap:11px;padding:11px 12px;border-radius:14px;color:rgba(22,35,30,.64);font-size:13px;font-weight:650;transition:.2s ease}.side-nav a:hover{background:rgba(9,37,29,.06);color:var(--pine-900)}.side-nav a.active{background:var(--pine-900);color:#fff}.side-nav svg{width:18px;height:18px;flex:0 0 auto}.side-help{padding:15px;border-radius:18px;background:var(--oat)}.side-help strong{display:block;font-family:"Fraunces",serif;font-size:17px}.side-help p{margin:7px 0 12px;color:rgba(22,35,30,.6);font-size:11px;line-height:1.55}.side-help a{color:var(--pine-900);font-size:12px;font-weight:800}
    .content{min-width:0}.hero{position:relative;overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) minmax(390px,.88fr);min-height:430px;border-radius:34px;background:var(--pine-900);color:#fff;box-shadow:var(--shadow)}.hero-copy{position:relative;z-index:4;display:flex;flex-direction:column;justify-content:center;padding:42px 44px}.eyebrow{display:inline-flex;align-items:center;gap:8px;width:max-content;padding:7px 10px;border:1px solid rgba(223,252,98,.22);border-radius:999px;background:rgba(223,252,98,.08);color:var(--acid);font-size:10px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.eyebrow-dot{width:7px;height:7px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 7px rgba(223,252,98,.1)}.hero h1{max-width:720px;margin:22px 0 14px;font-family:"Fraunces",serif;font-size:clamp(42px,5vw,72px);font-weight:600;letter-spacing:-.055em;line-height:.97}.hero h1 em{color:var(--acid);font-style:italic}.hero-copy>p{max-width:620px;margin:0;color:rgba(255,255,255,.66);font-size:15px;line-height:1.7}.hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:26px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 17px;border:0;border-radius:14px;cursor:pointer;font-size:13px;font-weight:800;transition:.22s ease}.btn-primary{background:var(--acid);color:var(--pine-950)}.btn-primary:hover{transform:translateY(-2px)}.btn-ghost{border:1px solid rgba(255,255,255,.17);background:rgba(255,255,255,.07);color:#fff}.hero-visual{position:relative;min-height:430px;display:grid;place-items:center;padding:34px}.hero-visual:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,var(--pine-900),rgba(9,37,29,.28) 28%,rgba(9,37,29,.1)),url("https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1500&q=86") center/cover;opacity:.78}.member-card{position:relative;z-index:4;width:min(390px,100%);aspect-ratio:1.58;padding:26px;border:1px solid rgba(255,255,255,.18);border-radius:27px;background:linear-gradient(135deg,rgba(255,255,255,.15),rgba(255,255,255,.045));box-shadow:0 35px 85px -35px rgba(0,0,0,.75);backdrop-filter:blur(20px);transform:rotate(-3deg)}.member-card:after{content:"";position:absolute;inset:0;border-radius:inherit;background:radial-gradient(circle at 84% 12%,rgba(223,252,98,.22),transparent 26%),linear-gradient(120deg,transparent 45%,rgba(255,255,255,.07) 52%,transparent 59%);pointer-events:none}.member-card-top,.member-card-bottom{position:relative;z-index:2;display:flex;justify-content:space-between;gap:16px}.member-card small{display:block;color:rgba(255,255,255,.5);font-size:8px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.member-card strong{display:block;margin-top:7px;font-family:"Fraunces",serif;font-size:25px}.member-card .level{padding:7px 10px;border-radius:999px;background:var(--acid);color:var(--pine-950);font-size:8px;font-weight:900}.member-card-mark{position:relative;z-index:2;display:grid;place-items:center;width:66px;height:66px;margin:28px 0 18px;border:1px solid rgba(223,252,98,.38);border-radius:23px;background:rgba(223,252,98,.08);color:var(--acid)}.member-card-bottom{align-items:end}.member-card-id{color:var(--acid);font-size:10px;font-weight:900;letter-spacing:.17em}.member-card-bottom time{text-align:right;font-size:11px;font-weight:700}.scan-hint{position:absolute;z-index:5;right:22px;bottom:20px;display:flex;align-items:center;gap:8px;padding:10px 12px;border:1px solid rgba(255,255,255,.16);border-radius:15px;background:rgba(6,26,21,.75);backdrop-filter:blur(16px);font-size:9px;font-weight:800}.scan-dot{width:8px;height:8px;border-radius:50%;background:var(--acid);box-shadow:0 0 0 7px rgba(223,252,98,.1)}
    .stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:16px 0 18px}.stat{padding:19px;border:1px solid var(--line);border-radius:21px;background:var(--cream);box-shadow:var(--card-shadow)}.stat-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.stat-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:var(--pine-900);color:var(--acid)}.stat-badge{padding:5px 7px;border-radius:999px;background:rgba(223,252,98,.35);color:var(--pine-900);font-size:8px;font-weight:900}.stat>strong{display:block;margin-top:17px;font-family:"Fraunces",serif;font-size:31px;line-height:1}.stat>span:last-child{display:block;margin-top:7px;color:rgba(22,35,30,.52);font-size:10px}
    .membership-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px}.stack{display:grid;gap:18px}.card{padding:24px;border:1px solid var(--line);border-radius:26px;background:var(--cream);box-shadow:var(--card-shadow)}.card-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:20px}.card-kicker{margin:0 0 6px;color:var(--pine-700);font-size:9px;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.card h2{margin:0;font-family:"Fraunces",serif;font-size:25px;font-weight:600;letter-spacing:-.035em}.link-arrow{display:inline-flex;align-items:center;gap:7px;color:var(--pine-900);font-size:11px;font-weight:800;white-space:nowrap;border:0;background:transparent;cursor:pointer}
    .benefits-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.benefit{position:relative;overflow:hidden;padding:18px;border-radius:20px;background:var(--oat);min-height:170px}.benefit.used{opacity:.72}.benefit-top{display:flex;justify-content:space-between;gap:12px}.benefit-icon{display:grid;place-items:center;width:42px;height:42px;border-radius:14px;background:var(--cream);color:var(--pine-900)}.benefit-count{padding:6px 8px;border-radius:999px;background:var(--cream);font-size:8px;font-weight:900}.benefit h3{margin:17px 0 6px;font-family:"Fraunces",serif;font-size:19px}.benefit p{margin:0;color:rgba(22,35,30,.57);font-size:10px;line-height:1.55}.benefit-footer{position:absolute;left:18px;right:18px;bottom:16px;display:flex;align-items:center;justify-content:space-between;gap:10px}.benefit-progress{flex:1;height:6px;overflow:hidden;border-radius:999px;background:rgba(9,37,29,.1)}.benefit-progress span{display:block;height:100%;border-radius:inherit;background:var(--pine-700)}.benefit-footer b{font-size:9px}.benefit button{border:0;background:transparent;color:var(--pine-900);font-size:9px;font-weight:900;cursor:pointer}
    .season-card{position:relative;overflow:hidden;padding:0;background:var(--pine-900);color:#fff}.season-cover{position:relative;min-height:210px;background:linear-gradient(180deg,rgba(6,26,21,.12),rgba(6,26,21,.87)),url("https://images.unsplash.com/photo-1500534314209-a25ddb2bd4297?auto=format&fit=crop&w=1500&q=84") center/cover}.season-copy{position:absolute;inset:auto 24px 22px}.season-copy .card-kicker{color:var(--acid)}.season-copy h2{font-size:30px}.season-body{padding:22px}.season-meta{display:flex;flex-wrap:wrap;gap:8px}.pill{display:inline-flex;align-items:center;gap:6px;padding:8px 10px;border-radius:12px;background:rgba(255,255,255,.07);font-size:9px;font-weight:700}.season-body p{margin:16px 0 20px;color:rgba(255,255,255,.63);font-size:11px;line-height:1.65}.season-actions{display:flex;gap:9px;flex-wrap:wrap}
    .events{display:grid;gap:10px}.event{display:grid;grid-template-columns:58px minmax(0,1fr) auto;gap:13px;align-items:center;padding:12px;border-radius:18px;background:var(--oat)}.event-date{display:grid;place-items:center;min-height:58px;border-radius:15px;background:var(--cream);font-family:"Fraunces",serif;font-size:19px}.event-date span{display:block;margin-top:-4px;font-family:"DM Sans",sans-serif;font-size:7px;font-weight:900;letter-spacing:.13em;text-transform:uppercase}.event strong{display:block;font-size:11px}.event p{margin:4px 0 0;color:rgba(22,35,30,.53);font-size:9px}.event-status{padding:6px 8px;border-radius:999px;background:rgba(223,252,98,.32);font-size:8px;font-weight:900}.event-status.wait{background:rgba(242,123,74,.14);color:#a54b27}
    .renew-card{background:linear-gradient(135deg,#dffc62,#efffb0)}.renew-card h2{font-size:27px}.renew-date{display:flex;justify-content:space-between;gap:14px;margin-top:20px;padding:15px;border-radius:18px;background:rgba(255,253,246,.72)}.renew-date small{display:block;color:rgba(22,35,30,.5);font-size:8px;text-transform:uppercase;font-weight:900;letter-spacing:.13em}.renew-date strong{display:block;margin-top:6px;font-family:"Fraunces",serif;font-size:18px}.renew-card p{margin:16px 0;color:rgba(22,35,30,.62);font-size:10px;line-height:1.6}.renew-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.renew-actions .btn{padding-inline:12px}.btn-dark{background:var(--pine-900);color:#fff}.btn-light{background:rgba(255,253,246,.7);color:var(--pine-900)}
    .points-card{background:var(--pine-900);color:#fff}.points-ring{position:relative;display:grid;place-items:center;width:152px;height:152px;margin:12px auto 20px;border-radius:50%;background:conic-gradient(var(--acid) 0 68%,rgba(255,255,255,.09) 68%)}.points-ring:before{content:"";position:absolute;inset:12px;border-radius:50%;background:var(--pine-900)}.points-ring span{position:relative;text-align:center}.points-ring strong{display:block;font-family:"Fraunces",serif;font-size:33px}.points-ring small{color:rgba(255,255,255,.52);font-size:8px;text-transform:uppercase;letter-spacing:.12em}.points-card p{margin:0;color:rgba(255,255,255,.59);font-size:10px;line-height:1.6;text-align:center}.points-card .btn{width:100%;margin-top:16px}
    .history{display:grid;gap:9px}.history-item{display:grid;grid-template-columns:auto 1fr auto;gap:11px;align-items:center;padding:11px;border-radius:16px;background:var(--oat)}.history-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:var(--cream);color:var(--pine-900)}.history-item strong{display:block;font-size:10px}.history-item span{display:block;margin-top:3px;color:rgba(22,35,30,.5);font-size:8px}.history-value{text-align:right;font-size:10px;font-weight:900}.history-value.plus{color:var(--pine-700)}
    .mobile-nav{display:none}.mobile-menu{position:fixed;inset:0;z-index:90;padding:16px;background:var(--pine-950);color:#fff;transform:translateX(100%);transition:.3s cubic-bezier(.22,.8,.2,1)}.mobile-menu.open{transform:none}.mobile-menu-head{display:flex;align-items:center;justify-content:space-between}.mobile-menu-links{display:grid;gap:8px;margin-top:34px}.mobile-menu-links a{padding:16px;border-bottom:1px solid rgba(255,255,255,.1);font-family:"Fraunces",serif;font-size:27px}
    .modal,.drawer{position:fixed;inset:0;z-index:100;background:rgba(6,26,21,.67);backdrop-filter:blur(12px);opacity:0;visibility:hidden;transition:.25s ease}.modal{display:grid;place-items:center;padding:20px}.modal.open,.drawer.open{opacity:1;visibility:visible}.modal-card{position:relative;width:min(440px,100%);padding:26px;border-radius:28px;background:var(--cream);box-shadow:0 40px 100px -30px rgba(0,0,0,.65);transform:translateY(14px) scale(.98);transition:.25s ease}.modal.open .modal-card{transform:none}.modal-close{position:absolute;right:14px;top:14px;display:grid;place-items:center;width:38px;height:38px;border:0;border-radius:13px;background:var(--oat);cursor:pointer}.modal h3,.drawer h3{margin:8px 0 7px;font-family:"Fraunces",serif;font-size:28px}.modal p,.drawer p{margin:0;color:rgba(22,35,30,.58);font-size:11px;line-height:1.6}.digital-pass{margin-top:20px;padding:20px;border-radius:23px;background:var(--pine-900);color:#fff}.digital-pass-head{display:flex;justify-content:space-between;gap:12px}.digital-pass small{display:block;color:rgba(255,255,255,.48);font-size:8px;font-weight:900;text-transform:uppercase;letter-spacing:.14em}.digital-pass strong{display:block;margin-top:5px;font-family:"Fraunces",serif;font-size:19px}.qr{width:148px;height:148px;margin:22px auto;background:repeating-conic-gradient(#09251d 0 25%,#fff 0 50%) 0 0/14px 14px;border:14px solid #fff}.pass-code{text-align:center;color:var(--acid);font-size:9px;font-weight:900;letter-spacing:.17em}.modal-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:14px}.drawer{display:flex;justify-content:flex-end}.drawer-panel{width:min(520px,100%);height:100%;overflow:auto;padding:26px;background:var(--cream);transform:translateX(100%);transition:.3s cubic-bezier(.22,.8,.2,1)}.drawer.open .drawer-panel{transform:none}.drawer-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.plan-options{display:grid;gap:10px;margin-top:22px}.plan-option{position:relative;display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;padding:15px;border:1px solid var(--line);border-radius:18px;background:var(--oat);cursor:pointer}.plan-option.selected{border-color:var(--pine-700);box-shadow:0 0 0 2px rgba(27,82,66,.08)}.plan-radio{width:18px;height:18px;border:2px solid rgba(9,37,29,.3);border-radius:50%}.selected .plan-radio{border:5px solid var(--pine-700)}.plan-option strong{display:block;font-size:11px}.plan-option span{display:block;margin-top:4px;color:rgba(22,35,30,.5);font-size:9px}.plan-price{font-family:"Fraunces",serif;font-size:19px}.drawer-summary{margin-top:20px;padding:16px;border-radius:18px;background:var(--pine-900);color:#fff}.drawer-summary-row{display:flex;justify-content:space-between;gap:12px;padding:7px 0;font-size:10px}.drawer-summary-row.total{margin-top:7px;padding-top:14px;border-top:1px solid rgba(255,255,255,.12);font-family:"Fraunces",serif;font-size:18px}.drawer-panel>.btn{width:100%;margin-top:14px}
    .toast{position:fixed;right:18px;bottom:18px;z-index:120;max-width:min(360px,calc(100% - 36px));padding:13px 16px;border-radius:16px;background:var(--pine-900);color:#fff;box-shadow:0 24px 60px -22px rgba(0,0,0,.85);font-size:10px;font-weight:700;transform:translateY(24px);opacity:0;pointer-events:none;transition:.25s ease}.toast.show{transform:none;opacity:1}
    @media(max-width:1180px){.layout{grid-template-columns:220px minmax(0,1fr)}.hero{grid-template-columns:1fr minmax(340px,.8fr)}.membership-grid{grid-template-columns:minmax(0,1fr) 310px}}
    @media(max-width:980px){.main-nav{display:none}.menu-btn{display:grid}.layout{grid-template-columns:1fr;padding-top:10px}.sidebar{display:none}.hero{grid-template-columns:1fr}.hero-copy{padding-bottom:22px}.hero-visual{min-height:360px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.membership-grid{grid-template-columns:1fr}.side-stack{grid-template-columns:repeat(2,minmax(0,1fr));align-items:start}}
    @media(max-width:640px){.shell{width:min(100% - 20px,1460px)}.site-header{padding:8px 0}.nav{padding:8px 9px 8px 11px;border-radius:18px;gap:8px}.brand-mark{width:38px;height:38px;border-radius:13px}.brand-copy strong{font-size:16px}.brand-copy span{display:none}.ticket-cta{min-height:38px;padding:0 12px;font-size:12px}.menu-btn{width:38px;height:38px}.layout{padding-bottom:104px}.hero{min-height:0;border-radius:27px}.hero-copy{padding:30px 22px 18px}.hero h1{font-size:43px}.hero-copy>p{font-size:13px}.hero-actions{display:grid;grid-template-columns:1fr 1fr}.hero-actions .btn{padding:0 12px}.hero-visual{min-height:310px;padding:24px 18px 52px}.member-card{width:min(330px,100%);padding:21px;transform:rotate(-2deg)}.member-card strong{font-size:21px}.member-card-mark{width:55px;height:55px;margin:20px 0 13px}.scan-hint{right:18px;bottom:14px}.stats{gap:8px;margin:10px 0 14px}.stat{padding:15px;border-radius:18px}.stat-icon{width:34px;height:34px}.stat>strong{font-size:27px}.card{padding:18px;border-radius:22px}.card-head{margin-bottom:16px}.card h2{font-size:22px}.benefits-grid{grid-template-columns:1fr}.benefit{min-height:165px}.season-cover{min-height:190px}.season-copy{inset:auto 18px 18px}.season-copy h2{font-size:26px}.event{grid-template-columns:50px minmax(0,1fr)}.event-status{grid-column:2;justify-self:start}.renew-actions{grid-template-columns:1fr}.side-stack{grid-template-columns:1fr}.mobile-nav{position:fixed;left:10px;right:10px;bottom:max(10px,env(safe-area-inset-bottom));z-index:60;display:grid;grid-template-columns:repeat(4,1fr);padding:7px;border:1px solid rgba(255,255,255,.12);border-radius:20px;background:rgba(6,26,21,.92);backdrop-filter:blur(20px);box-shadow:0 24px 60px -24px rgba(0,0,0,.8)}.mobile-nav a{display:grid;place-items:center;gap:4px;min-height:52px;border-radius:14px;color:rgba(255,255,255,.54);font-size:8px;font-weight:800}.mobile-nav a.active{background:rgba(223,252,98,.12);color:var(--acid)}.mobile-nav svg{width:19px;height:19px}.modal{padding:10px;align-items:end}.modal-card{padding:22px;border-radius:25px 25px 18px 18px;max-height:88vh;overflow:auto}.modal-actions{grid-template-columns:1fr}.drawer{align-items:flex-end}.drawer-panel{width:100%;height:auto;max-height:92vh;border-radius:26px 26px 0 0;transform:translateY(100%);padding:22px 18px calc(22px + env(safe-area-inset-bottom))}.drawer.open .drawer-panel{transform:none}.plan-option{grid-template-columns:auto minmax(0,1fr)}.plan-price{grid-column:2;font-size:17px}.toast{bottom:92px}.history-item{grid-template-columns:auto minmax(0,1fr)}.history-value{grid-column:2;text-align:left}}
    @media(max-width:390px){.hero h1{font-size:38px}.hero-actions{grid-template-columns:1fr}.stats{grid-template-columns:1fr 1fr}.member-card{padding:18px}.member-card-mark{margin:15px 0 10px}.member-card-id{font-size:8px}.renew-date{display:grid}.modal h3,.drawer h3{font-size:25px}}
    @media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
