    <section class="content">
      <section class="hero grain topo" aria-labelledby="pageTitle">
        <div class="hero-copy"><span class="eyebrow"><span class="eyebrow-dot"></span>Membership activ</span><h1 id="pageTitle">Wild Circle îți deschide <em>tot sezonul</em>.</h1><p>Acces prioritar, invitați, evenimente private și beneficii care se reactivează pe măsură ce explorezi parcul.</p><div class="hero-actions"><button class="btn btn-primary" id="openPass" type="button">Arată cardul digital</button><button class="btn btn-ghost" id="openUpgrade" type="button">Upgrade membership</button></div></div>
        <div class="hero-visual"><div class="member-card" aria-label="Card digital Wild Circle"><div class="member-card-top"><span><small>Nordvale membership</small><strong>Wild Circle</strong></span><span class="level">Activ</span></div><div class="member-card-mark"><svg width="36" height="36" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M12 2 5 6v6c0 5 3 8 7 10 4-2 7-5 7-10V6z"/><path d="m8 14 3-6 2 4 3-2"/></svg></div><div class="member-card-bottom"><span><small>Membru</small><strong>Andrei Popescu</strong><span class="member-card-id">NV-WC-026184</span></span><time><small>Valabil până la</small>31.05.2027</time></div></div><button class="scan-hint" id="scanCard" type="button"><span class="scan-dot"></span>Deschide pentru scanare</button></div>
      </section>

      <section class="stats" aria-label="Rezumat membership">
        <article class="stat"><div class="stat-top"><span class="stat-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 19c5-2 7-7 8-14 3 5 6 8 8 14"/></svg></span><span class="stat-badge">Sezon 2026</span></div><strong>8</strong><span>Vizite înregistrate</span></article>
        <article class="stat"><div class="stat-top"><span class="stat-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="8" cy="9" r="3"/><circle cx="16" cy="9" r="3"/><path d="M3 20c.7-4 2.7-6 5-6M21 20c-.7-4-2.7-6-5-6"/></svg></span></div><strong>2</strong><span>Invitații rămase</span></article>
        <article class="stat"><div class="stat-top"><span class="stat-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3v18M3 12h18"/></svg></span></div><strong>240</strong><span>Puncte disponibile</span></article>
        <article class="stat"><div class="stat-top"><span class="stat-icon"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 4h14v16H5z"/><path d="M8 9h8M8 13h5"/></svg></span></div><strong>418 lei</strong><span>Economie estimată</span></article>
      </section>

      <section class="membership-grid">
        <div class="stack">
          <article class="card"><div class="card-head"><span><p class="card-kicker">Beneficiile tale</p><h2>Ce mai poți folosi în acest sezon.</h2></span><button class="link-arrow" id="showAllBenefits" type="button">Vezi regulamentul →</button></div>
            <div class="benefits-grid">
              <article class="benefit"><div class="benefit-top"><span class="benefit-icon"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16v10H4z"/><path d="M8 11h8"/></svg></span><span class="benefit-count">2 din 4</span></div><h3>Invitații pentru prieteni</h3><p>Două accesuri gratuite mai sunt disponibile până la finalul sezonului.</p><div class="benefit-footer"><div class="benefit-progress"><span style="width:50%"></span></div><button type="button" data-action="invite">Folosește</button></div></article>
              <article class="benefit"><div class="benefit-top"><span class="benefit-icon"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 3v3M19 3v3M4 8h16v13H4z"/><path d="M8 12h8"/></svg></span><span class="benefit-count">Disponibil</span></div><h3>Rezervare prioritară</h3><p>Acces cu 72 de ore înaintea publicului la datele cu cerere mare.</p><div class="benefit-footer"><div class="benefit-progress"><span style="width:100%"></span></div><button type="button" data-action="calendar">Rezervă</button></div></article>
              <article class="benefit"><div class="benefit-top"><span class="benefit-icon"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 19c5-2 7-7 8-14 3 5 6 8 8 14"/></svg></span><span class="benefit-count">1 din 3</span></div><h3>Tururi ghidate</h3><p>Două tururi de natură sau orientare mai pot fi rezervate fără cost.</p><div class="benefit-footer"><div class="benefit-progress"><span style="width:34%"></span></div><button type="button" data-action="tour">Alege turul</button></div></article>
              <article class="benefit used"><div class="benefit-top"><span class="benefit-icon"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h10l2 5-7 13L5 8z"/></svg></span><span class="benefit-count">Utilizat</span></div><h3>Upgrade Canopy Run</h3><p>Upgrade-ul gratuit pentru o experiență premium a fost folosit în luna iunie.</p><div class="benefit-footer"><div class="benefit-progress"><span style="width:100%"></span></div><b>Reactivare în 2027</b></div></article>
            </div>
          </article>

          <article class="card season-card"><div class="season-cover"><div class="season-copy"><p class="card-kicker">Eveniment privat pentru membri</p><h2>Night Trails: licurici și orientare.</h2></div></div><div class="season-body"><div class="season-meta"><span class="pill">22 august · 20:30</span><span class="pill">24 locuri</span><span class="pill">Inclus în membership</span></div><p>Un traseu nocturn ghidat prin zona protejată, cu stații de observație și o masă caldă la Forest Lodge.</p><div class="season-actions"><button class="btn btn-primary" id="reserveEvent" type="button">Rezervă două locuri</button><button class="btn btn-ghost" id="eventDetails" type="button">Vezi programul</button></div></div></article>

          <article class="card"><div class="card-head"><span><p class="card-kicker">Calendarul membrilor</p><h2>Următoarele experiențe private.</h2></span><a class="link-arrow" href="/calendar">Calendar complet →</a></div><div class="events">
            <article class="event"><time class="event-date">22<span>aug</span></time><span><strong>Night Trails</strong><p>Traseu nocturn ghidat · 20:30</p></span><span class="event-status">Rezervabil</span></article>
            <article class="event"><time class="event-date">06<span>sep</span></time><span><strong>Forest Breakfast</strong><p>Mic dejun în poiana Nord · 08:00</p></span><span class="event-status">12 locuri</span></article>
            <article class="event"><time class="event-date">19<span>sep</span></time><span><strong>Canopy After Hours</strong><p>Sesiune exclusivă · 19:00</p></span><span class="event-status wait">Listă de așteptare</span></article>
          </div></article>
        </div>

        <aside class="stack side-stack">
          <article class="card renew-card"><p class="card-kicker">Reînnoire</p><h2>Prețul actual este protejat.</h2><div class="renew-date"><span><small>Expiră la</small><strong>31 mai 2027</strong></span><span><small>Reînnoire</small><strong>690 lei</strong></span></div><p>Poți activa reînnoirea automată acum sau poți trece la Summit Society, cu acces nelimitat la experiențele premium.</p><div class="renew-actions"><button class="btn btn-dark" id="renewButton" type="button">Reînnoire</button><button class="btn btn-light" id="upgradeButton" type="button">Compară nivelurile</button></div></article>
          <article class="card points-card"><p class="card-kicker" style="color:var(--acid)">Adventure points</p><div class="points-ring"><span><strong>240</strong><small>din 350</small></span></div><p>Mai ai nevoie de 110 puncte pentru o experiență Canopy Run gratuită.</p><button class="btn btn-primary" id="pointsButton" type="button">Vezi recompensele</button></article>
          <article class="card"><div class="card-head"><span><p class="card-kicker">Activitate</p><h2>Istoric membership</h2></span></div><div class="history">
            <article class="history-item"><span class="history-icon"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 3v3M19 3v3M4 8h16v13H4z"/></svg></span><span><strong>Vizită înregistrată</strong><span>Canopy Run Day · 12 iulie</span></span><span class="history-value plus">+40 pct</span></article>
            <article class="history-item"><span class="history-icon"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16v10H4z"/></svg></span><span><strong>Invitație utilizată</strong><span>Mara Popescu · 12 iulie</span></span><span class="history-value">1 acces</span></article>
            <article class="history-item"><span class="history-icon"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 3h10l2 5-7 13L5 8z"/></svg></span><span><strong>Upgrade activat</strong><span>Canopy Run · 08 iunie</span></span><span class="history-value">Inclus</span></article>
          </div></article>
        </aside>
      </section>
    </section>
  </main>

  <nav class="mobile-nav" aria-label="Navigație cont mobil"><a href="/cont"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/></svg>Acasă</a><a href="/cont/bilete"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16v4a2 2 0 0 0 0 4v4H4v-4a2 2 0 0 0 0-4z"/></svg>Bilete</a><a href="/cont/comenzi"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 4h14v16H5z"/></svg>Comenzi</a><a class="active" href="#"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 6h16v12H4z"/><path d="M8 10h8"/></svg>Abonament</a></nav>

  <div class="mobile-menu" id="mobileMenu" aria-hidden="true"><div class="mobile-menu-head"><a class="brand" href="/"><span class="brand-mark"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m4 17 5-10 3 6 2-4 6 8"/><path d="M3 20h18"/></svg></span><span class="brand-copy"><strong>Nordvale</strong><span>Wild Park & Forest Reserve</span></span></a><button class="menu-btn" id="menuClose" type="button" aria-label="Închide meniul"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="mobile-menu-links"><a href="/experiente">Experiențe</a><a href="/planifica">Planifică vizita</a><a href="/calendar">Calendar</a><a href="/bilete">Bilete</a><a href="/autentificare">Deconectare</a></div></div>

  <div class="modal" id="passModal" aria-hidden="true"><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="passTitle"><button class="modal-close" id="passClose" type="button" aria-label="Închide"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button><p class="card-kicker">Card digital</p><h3 id="passTitle">Wild Circle</h3><p>Prezintă codul la porțile parcului sau la evenimentele private pentru membri.</p><div class="digital-pass"><div class="digital-pass-head"><span><small>Membru</small><strong>Andrei Popescu</strong></span><span><small>Valabil</small><strong>31.05.2027</strong></span></div><div class="qr" aria-label="Cod QR demonstrativ"></div><div class="pass-code">NV-WC-026184</div></div><div class="modal-actions"><button class="btn btn-primary" id="walletButton" type="button">Adaugă în Wallet</button><button class="btn" id="copyButton" type="button" style="background:var(--oat);color:var(--pine-900)">Copiază ID-ul</button></div></div></div>

  <div class="drawer" id="upgradeDrawer" aria-hidden="true"><div class="drawer-panel" role="dialog" aria-modal="true" aria-labelledby="upgradeTitle"><div class="drawer-head"><span><p class="card-kicker">Membership 2027</p><h3 id="upgradeTitle">Reînnoiește sau schimbă nivelul.</h3><p>Prețurile și beneficiile sunt demonstrative.</p></span><button class="modal-close" id="upgradeClose" type="button" aria-label="Închide"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="m6 6 12 12M18 6 6 18"/></svg></button></div><div class="plan-options" id="planOptions"><button class="plan-option selected" type="button" data-plan="wild" data-price="690"><span class="plan-radio"></span><span><strong>Wild Circle</strong><span>Păstrezi beneficiile actuale și prețul protejat.</span></span><span class="plan-price">690 lei</span></button><button class="plan-option" type="button" data-plan="summit" data-price="1190"><span class="plan-radio"></span><span><strong>Summit Society</strong><span>Acces premium, 6 invitații și evenimente cu loc garantat.</span></span><span class="plan-price">1.190 lei</span></button></div><div class="drawer-summary"><div class="drawer-summary-row"><span>Nivel selectat</span><strong id="selectedPlanLabel">Wild Circle</strong></div><div class="drawer-summary-row"><span>Începe la</span><strong>1 iunie 2027</strong></div><div class="drawer-summary-row total"><span>Total</span><strong id="selectedPlanPrice">690 lei</strong></div></div><button class="btn btn-primary" id="confirmUpgrade" type="button">Confirmă alegerea</button></div></div>
  <div class="toast" id="toast" role="status" aria-live="polite"></div>

  <script>
    (()=>{'use strict';const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];const body=document.body,menu=$('#mobileMenu'),modal=$('#passModal'),drawer=$('#upgradeDrawer'),toast=$('#toast');
      const lock=()=>body.style.overflow='hidden',unlock=()=>body.style.overflow='';
      const openMenu=()=>{menu?.classList.add('open');menu?.setAttribute('aria-hidden','false');lock()};const closeMenu=()=>{menu?.classList.remove('open');menu?.setAttribute('aria-hidden','true');unlock()};
      const openModal=()=>{modal?.classList.add('open');modal?.setAttribute('aria-hidden','false');lock();$('#passClose')?.focus()};const closeModal=()=>{modal?.classList.remove('open');modal?.setAttribute('aria-hidden','true');unlock()};
      const openDrawer=()=>{drawer?.classList.add('open');drawer?.setAttribute('aria-hidden','false');lock()};const closeDrawer=()=>{drawer?.classList.remove('open');drawer?.setAttribute('aria-hidden','true');unlock()};
      const showToast=message=>{if(!toast)return;toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),2600)};
      $('#menuOpen')?.addEventListener('click',openMenu);$('#menuClose')?.addEventListener('click',closeMenu);$('#openPass')?.addEventListener('click',openModal);$('#scanCard')?.addEventListener('click',openModal);$('#passClose')?.addEventListener('click',closeModal);modal?.addEventListener('click',e=>{if(e.target===modal)closeModal()});
      ['#openUpgrade','#upgradeButton','#renewButton'].forEach(id=>$(id)?.addEventListener('click',openDrawer));$('#upgradeClose')?.addEventListener('click',closeDrawer);drawer?.addEventListener('click',e=>{if(e.target===drawer)closeDrawer()});
      document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMenu();closeModal();closeDrawer()}});
      $('#walletButton')?.addEventListener('click',()=>showToast('Cardul digital a fost adăugat în Wallet.'));$('#copyButton')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText('NV-WC-026184');showToast('ID-ul de membru a fost copiat.')}catch{showToast('ID membru: NV-WC-026184')}});
      $('#reserveEvent')?.addEventListener('click',()=>showToast('Două locuri au fost rezervate pentru Night Trails.'));$('#eventDetails')?.addEventListener('click',()=>document.querySelector('.events')?.scrollIntoView({behavior:'smooth',block:'center'}));$('#pointsButton')?.addEventListener('click',()=>showToast('Recompensele vor fi disponibile în următorul ecran.'));$('#showAllBenefits')?.addEventListener('click',()=>showToast('Regulamentul membership-ului este demonstrativ.'));
      $$('[data-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.action;if(action==='calendar')location.href='/calendar';else showToast(action==='invite'?'Selectează o dată pentru invitații din calendar.':'Tururile disponibile au fost încărcate.')}));
      $$('.plan-option').forEach(button=>button.addEventListener('click',()=>{$$('.plan-option').forEach(x=>x.classList.remove('selected'));button.classList.add('selected');$('#selectedPlanLabel').textContent=button.dataset.plan==='summit'?'Summit Society':'Wild Circle';$('#selectedPlanPrice').textContent=Number(button.dataset.price).toLocaleString('ro-RO')+' lei'}));
      $('#confirmUpgrade')?.addEventListener('click',()=>{const label=$('#selectedPlanLabel')?.textContent||'membership';closeDrawer();showToast(`${label} a fost selectat pentru reînnoire.`)});
      if(!matchMedia('(prefers-reduced-motion: reduce)').matches){$$('.hero-copy > *').forEach((el,i)=>el.animate([{opacity:0,transform:'translateY(22px)'},{opacity:1,transform:'translateY(0)'}],{duration:620,delay:70+i*75,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'}));$('.member-card')?.animate([{opacity:0,transform:'translateY(26px) rotate(-7deg) scale(.96)'},{opacity:1,transform:'translateY(0) rotate(-3deg) scale(1)'}],{duration:900,delay:190,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.animate([{opacity:0,transform:'translateY(16px)'},{opacity:1,transform:'translateY(0)'}],{duration:500,easing:'cubic-bezier(.22,.8,.2,1)',fill:'both'});observer.unobserve(entry.target)}}),{threshold:.1});$$('.stat,.card').forEach(el=>observer.observe(el))}
    })();
  </script>
  <script>
  (function(){
    function nvAuth(){ try { return JSON.parse(localStorage.getItem('nordvale_auth')||'null'); } catch(e){ return null; } }
    var a = nvAuth();
    if(!a || !a.token){ location.href='/autentificare?next='+encodeURIComponent(location.pathname+location.search); return; }
    var AH = { 'Authorization':'Bearer '+a.token };
    function api(ac,opt){ opt=opt||{}; opt.headers=Object.assign({},AH,opt.headers||{}); return fetch('/api/proxy.php?action='+ac,opt).then(function(r){return r.json().catch(function(){return{};});}).catch(function(){return{};}); }
    function post(ac,b){ return api(ac,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b||{})}); }
    function esc(s){ var d=document.createElement('div'); d.textContent=(s==null?'':String(s)); return d.innerHTML; }
    function initials(n){ n=(n||'').trim(); if(!n)return 'N'; var p=n.split(/\s+/); return (((p[0]||'')[0]||'')+((p[1]||'')[0]||'')).toUpperCase()||'N'; }
    function fmtDate(iso){ if(!iso)return ''; var d=new Date(iso); if(isNaN(d))return ''; return d.toLocaleDateString('ro-RO',{day:'2-digit',month:'short',year:'numeric'}); }
    function hydrateUser(u){ if(!u)return; var name=u.name||(((u.first_name||'')+' '+(u.last_name||'')).trim())||'Cont Nordvale'; window.__nvName=name; var box=document.querySelector('.profile-mini'); if(box){ var av=box.querySelector('.avatar'); if(av)av.textContent=initials(name); var st=box.querySelector('strong'); if(st)st.textContent=name; var em=box.querySelector('strong + span'); if(em&&u.email)em.textContent=u.email; } }
    document.querySelectorAll('a,button').forEach(function(el){ if((el.textContent||'').trim()==='Deconectare'){ el.addEventListener('click',function(ev){ ev.preventDefault(); post('logout').finally(function(){ localStorage.removeItem('nordvale_auth'); location.href='/'; }); }); } });
    hydrateUser(a.user);
    api('me').then(function(d){ if(d&&d.success&&d.data){ a.user=Object.assign({},a.user,d.data); try{localStorage.setItem('nordvale_auth',JSON.stringify(a));}catch(e){} hydrateUser(a.user); } });

    api('my-subscriptions').then(function(d){ if(!(d&&d.success&&Array.isArray(d.data))||!d.data.length)return; var s=d.data[0]; var nm=window.__nvName||'';
      var mc=document.querySelector('.member-card'); if(mc){ var top=mc.querySelector('.member-card-top strong'); if(top&&s.name)top.textContent=s.name; var lvl=mc.querySelector('.level'); if(lvl)lvl.textContent=(s.status==='active'?'Activ':(s.status||'')); var mm=mc.querySelector('.member-card-bottom strong'); if(mm&&nm)mm.textContent=nm; var vt=mc.querySelector('time'); if(vt&&s.valid_until){ vt.innerHTML='<small>Valabil până la</small>'+esc(fmtDate(s.valid_until)); } }
      var rd=document.querySelectorAll('.renew-date strong'); if(rd[0]&&s.valid_until)rd[0].textContent=fmtDate(s.valid_until);
      if(Array.isArray(s.benefits)&&s.benefits.length){ var bg=document.querySelector('.benefits-grid'); if(bg){ bg.innerHTML=s.benefits.map(function(b){ var txt=(typeof b==='string')?b:(b.name||b.title||b.label||''); if(!txt)return ''; return '<article class="benefit"><div class="benefit-top"><span class="benefit-icon"><svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m5 12 4 4 10-10"/></svg></span><span class="benefit-count">Inclus</span></div><h3>'+esc(txt)+'</h3><p>Beneficiu inclus în abonamentul tău.</p><div class="benefit-footer"><div class="benefit-progress"><span style="width:100%"></span></div></div></article>'; }).join(''); } }
    });
  })();
  </script>
</body>
</html>
